1	// Acceptance test for the change request:
2	//   "Work out for me whether an invoice is paid, part paid or still owing. Base it on the payments
3	//    I have recorded. I do not want to flip it to paid by hand anymore."
4	//
5	// Whether an invoice is PAID, PART PAID or STILL OWING is now WORKED OUT from the payments recorded
6	// against it — never set by hand. On the invoice's own detail page (invoice-detail-page, the child
7	// route /invoices/<id>, which is also where its payments are listed and recorded) a new panel
8	// (invoice-status-panel) reports that worked-out status:
9	//   - nothing paid yet            -> still owing
10	//   - some paid, but not the whole amount -> part paid
11	//   - payments cover the amount   -> paid
12	// The status is derived from the invoice's amount and the sum of its payments, so recording a
13	// payment can move it owing -> part paid -> paid with no manual step, and it is held by the server
14	// (survives a fresh load). Because the request wants a record kept for the payments it is based on,
15	// recording a payment appends exactly one audit record `PAYMENT_RECORDED id=<id> amount=<amount>`.
16	// The old by-hand "mark paid" control is gone: an invoice is no longer flipped to paid by hand.
17	//
18	// Asserts ONLY through the two public channels: the UI (data-testid) and the audit file
19	// (auditLines()). Data is arranged via resetAndSeed (the app's /__test__ endpoint): `clients` honours
20	// { id, name, email }, `projects` honours { id, name, clientId }, `invoices` honours
21	// { id, amount, projectId, status } and `payments` honours { id, invoiceId, amount, date }.
22	import { test, expect, type Page, type Locator } from '@playwright/test';
23	import { resetAndSeed } from '../support/seed';
24	import { auditLines } from '../support/audit';
25	
26	// Each worked-out status is matched by the WORD that names it, case-insensitively, so the test binds
27	// to the MEANING and not one capitalisation or exact phrasing ("Owing"/"Still owing",
28	// "Part paid"/"Partly paid"/"Partially paid", "Paid"/"Paid in full"). The three words cannot
29	// legitimately co-occur in the one concise status a panel shows, so they discriminate the states:
30	//   - only the owing status carries "owing";
31	//   - only the part-paid status carries "part";
32	//   - "paid" appears in both "paid" and "part paid", so FULLY paid is "paid" WITHOUT "part".
33	// PAID uses a word boundary so it binds to the word "paid" on its own and not a substring of
34	// "unpaid", keeping the owing assertion below robust to that wording too.
35	const OWING = /owing/i;
36	const PART = /part/i;
37	const PAID = /\bpaid\b/i;
38	
39	const paymentRows = (page: Page) => page.locator('[data-testid^="payment-row-"]');
40	const rowByAmount = (page: Page, amount: number): Locator =>
41	  paymentRows(page).filter({ has: page.getByTestId('payment-amount').getByText(String(amount)) });
42	
43	// The audit record kept for one recorded payment. The id is server-assigned, so it is matched as any
44	// number; the amount (the figure the status is based on) is pinned, allowing an optional scale part
45	// (150 or 150.00). Payment amounts in each test are chosen distinct so a record is found by amount.
46	const paymentRecord = (amount: number) =>
47	  new RegExp(`^PAYMENT_RECORDED id=\\d+ amount=${amount}(\\.\\d+)?$`);
48	const paymentRecordsFor = (amount: number): string[] =>
49	  auditLines().filter((line) => paymentRecord(amount).test(line));
50	
51	async function gotoInvoice(page: Page, id: number): Promise<void> {
52	  await page.goto(`/invoices/${id}`);
53	  await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
54	}
55	
56	const statusPanel = (page: Page): Locator => page.getByTestId('invoice-status-panel');
57	
58	type Status = 'owing' | 'part' | 'paid';
59	
60	// Assert the panel reports exactly one of the three worked-out statuses. Each case pins the status by
61	// its own word AND rules out the neighbours it must be distinguished from, so a panel hardwired to a
62	// single status could not pass all three scenarios below.
63	async function expectStatus(page: Page, status: Status): Promise<void> {
64	  const panel = statusPanel(page);
65	  await expect(panel).toBeVisible();
66	  if (status === 'owing') {
67	    await expect(panel).toHaveText(OWING);
68	    await expect(panel).not.toHaveText(PAID); // nothing paid: not "paid", not "part paid"
69	  } else if (status === 'part') {
70	    await expect(panel).toHaveText(PART);
71	    await expect(panel).not.toHaveText(OWING); // some paid: no longer merely owing
72	  } else {
73	    await expect(panel).toHaveText(PAID);
74	    await expect(panel).not.toHaveText(PART); // fully paid, not part paid
75	    await expect(panel).not.toHaveText(OWING);
76	  }
77	}
78	
79	test.describe('An invoice’s status is worked out from its payments', () => {
80	  test('with nothing paid yet, the invoice is still owing', async ({ page }) => {
81	    await resetAndSeed({
82	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
83	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
84	      invoices: [{ id: 1, amount: 500, projectId: 1, status: 'SENT' }],
85	      payments: [],
86	    });
87	
88	    await gotoInvoice(page, 1);
89	
90	    // No payments recorded, so the whole amount is outstanding: still owing.
91	    await expectStatus(page, 'owing');
92	  });
93	
94	  test('with some but not all of the amount paid, the invoice is part paid', async ({ page }) => {
95	    // Amount 500 with 60 + 175 = 235 paid against it: paid something, but not the whole amount.
96	    await resetAndSeed({
97	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
98	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
99	      invoices: [{ id: 1, amount: 500, projectId: 1, status: 'SENT' }],
100	      payments: [
101	        { id: 1, invoiceId: 1, amount: 60, date: '2021-03-14' },
102	        { id: 2, invoiceId: 1, amount: 175, date: '2022-08-19' },
103	      ],
104	    });
105	
106	    await gotoInvoice(page, 1);
107	
108	    await expectStatus(page, 'part');
109	  });
110	
111	  test('once payments cover the amount, the invoice is paid', async ({ page }) => {
112	    // Invoice 1: amount 300, 120 + 180 = 300 paid (covers it exactly) -> paid.
113	    // Invoice 2: amount 200, 250 paid (more than the amount) -> still paid: cover is cover.
114	    await resetAndSeed({
115	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
116	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
117	      invoices: [
118	        { id: 1, amount: 300, projectId: 1, status: 'SENT' },
119	        { id: 2, amount: 200, projectId: 1, status: 'SENT' },
120	      ],
121	      payments: [
