1	// Acceptance test for the change request:
2	//   "I want a home screen. Show me how many clients and projects I have. Show me how much money I
3	//    am still owed."
4	//
5	// A new dashboard page (dashboard-page, holding the dashboard region) is reachable from the nav
6	// (nav-dashboard). It summarises the whole app through three figures:
7	//   - dashboard-clients-count     — how many clients there are
8	//   - dashboard-projects-count    — how many projects there are
9	//   - dashboard-outstanding-total — how much money is STILL OWED, i.e. the amount of the invoices
10	//                                   I have actually SENT and not yet been paid for. A DRAFT has not
11	//                                   been sent, so it is not money I am owed; a PAID invoice is no
12	//                                   longer owed. Only SENT invoices count toward the total.
13	// While its data is loading it shows dashboard-loading, and if that data cannot be loaded it shows
14	// dashboard-error instead of fabricating figures.
15	//
16	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
17	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId } and
18	// `invoices` honours { id, amount, projectId, status }.
19	import { test, expect, type Page, type Locator } from '@playwright/test';
20	import { resetAndSeed } from '../support/seed';
21	
22	// A count or a money figure may be rendered bare (3, 350) or dressed up ("3 clients", "$350.00").
23	// Assert the figure CARRIES the expected number as a standalone token, so the test binds to the
24	// meaning rather than to one presentation. The surrounding (^|\D)…(\D|$) keeps a smaller number
25	// from matching inside a larger one (350 must not satisfy a check for 50, nor 0 match inside 350).
26	const asToken = (n: number) => new RegExp(`(^|\\D)${n}(\\D|$)`);
27	
28	const shows = (cell: Locator, n: number) => expect(cell).toContainText(asToken(n));
29	const hides = (cell: Locator, n: number) => expect(cell).not.toContainText(asToken(n));
30	
31	const clientsCount = (page: Page) => page.getByTestId('dashboard-clients-count');
32	const projectsCount = (page: Page) => page.getByTestId('dashboard-projects-count');
33	const outstanding = (page: Page) => page.getByTestId('dashboard-outstanding-total');
34	
35	// Reach the dashboard the way a user would: follow its nav link from the home screen. This avoids
36	// pinning the dashboard's URL — the contract is the nav link and the page it lands on.
37	async function openDashboard(page: Page): Promise<void> {
38	  await page.goto('/');
39	  const nav = page.getByTestId('nav-dashboard');
40	  await expect(nav).toBeVisible();
41	  await nav.click();
42	  await expect(page.getByTestId('dashboard-page')).toBeVisible();
43	  await expect(page.getByTestId('dashboard')).toBeVisible();
44	}
45	
46	test.describe('Dashboard home screen', () => {
47	  test('a link in the nav opens the dashboard', async ({ page }) => {
48	    await resetAndSeed({ clients: [], projects: [], invoices: [] });
49	
50	    await page.goto('/');
