98	    // It is the amount OWED — not the total ever invoiced (920), not the amount already paid (400),
99	    // and not the unsent draft (170), which is not money I am owed. Nor is it drafts-and-sent lumped
100	    // together (520): only what has actually been sent counts.
101	    await hides(outstanding(page), 920);
102	    await hides(outstanding(page), 400);
103	    await hides(outstanding(page), 170);
104	    await hides(outstanding(page), 520);
