121	    // already PAID and one is still a DRAFT that has not been sent. So nothing is still owed even
122	    // though money has been invoiced.
123	    await resetAndSeed({
124	      clients: [
125	        { id: 1, name: 'Acme Corp', email: 'hello@acme.test' },
126	        { id: 2, name: 'Globex', email: 'contact@globex.test' },
127	      ],
128	      projects: [
129	        { id: 1, name: 'Website Redesign', clientId: 1 },
130	        { id: 2, name: 'Mobile App', clientId: 2 },
131	      ],
132	      invoices: [
133	        { id: 1, amount: 400, projectId: 1, status: 'PAID' },
