138	
139	    await openDashboard(page);
140	
141	    await shows(clientsCount(page), 2);
142	    await shows(projectsCount(page), 2);
143	
144	    // Nothing is still owed: the paid invoices and the unsent draft are not money owed.
145	    await shows(outstanding(page), 0);
146	    await hides(outstanding(page), 400);
147	    await hides(outstanding(page), 350);
148	    await hides(outstanding(page), 500);
149	    await hides(outstanding(page), 750); // the paid pair
150	    await hides(outstanding(page), 1250); // everything invoiced
151	  });
152	
153	  test('while its data is loading it shows a loading indicator, then the figures', async ({
154	    page,
155	  }) => {
156	    await resetAndSeed({
157	      clients: [
158	        { id: 1, name: 'Acme Corp', email: 'hello@acme.test' },
