package net.officefloor.hq.app;

import java.math.BigDecimal;
import net.officefloor.web.ObjectResponse;

/**
 * {@code GET /api/dashboard} — the cross-feature summary the home dashboard shows: how many clients
 * and projects exist, and how much money is still owed (the sum of SENT invoice amounts across all
 * projects — only invoices that have actually been sent count; DRAFT and PAID are excluded). Wired by
 * {@code officefloor/rest/api/dashboard.GET.yml}.
 */
public class DashboardGetLogic {

    public void service(ClientRepository clients, ProjectRepository projects,
            InvoiceRepository invoices, ObjectResponse<DashboardView> response) {
        BigDecimal outstanding = invoices.findAll().stream()
                .filter(i -> "SENT".equals(i.getStatus()))
                .map(Invoice::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        response.send(new DashboardView(clients.count(), projects.count(), outstanding));
    }

    /** The counts and outstanding total the dashboard renders. */
    public static class DashboardView {
        private final long clientsCount;
        private final long projectsCount;
        private final BigDecimal outstandingTotal;

        public DashboardView(long clientsCount, long projectsCount, BigDecimal outstandingTotal) {
            this.clientsCount = clientsCount;
            this.projectsCount = projectsCount;
            this.outstandingTotal = outstandingTotal;
        }

        public long getClientsCount() {
            return clientsCount;
        }

        public long getProjectsCount() {
            return projectsCount;
        }

        public BigDecimal getOutstandingTotal() {
            return outstandingTotal;
        }
    }
}
package net.officefloor.hq.app;

import java.math.BigDecimal;

/**
 * Works out an invoice's status from the payments recorded against it, instead of a hand-set flag: a
 * DRAFT (not yet sent) keeps its stored lifecycle status, but once an invoice is SENT its status is
 * derived — SENT while nothing is paid, PARTIAL once some of the amount is covered, and PAID once the
 * payments cover it in full. Kept in one place so the per-project list, the invoice detail page and
 * the all-invoices view all agree on the same rule.
 */
public final class InvoiceStatus {

    private InvoiceStatus() {
    }

    /**
     * @param baseStatus the invoice's stored lifecycle status (e.g. DRAFT, SENT).
     * @param amount     what the invoice totals (its line items), null-safe.
     * @param paid       the sum of its payments, null-safe.
     * @return the status to show: the stored status for anything not yet SENT; otherwise SENT /
     *         PARTIAL / PAID worked out from the payments.
     */
    public static String derive(String baseStatus, BigDecimal amount, BigDecimal paid) {
        if (!"SENT".equals(baseStatus)) {
            // Not yet sent — payments do not apply; keep the lifecycle status as stored.
            return baseStatus;
        }
        BigDecimal paidAmount = paid != null ? paid : BigDecimal.ZERO;
        if (paidAmount.signum() <= 0) {
            return "SENT";
        }
        if (amount != null && paidAmount.compareTo(amount) >= 0) {
            return "PAID";
        }
        return "PARTIAL";
    }
}
===SEND LOGIC===
package net.officefloor.hq.app;

import java.math.RoundingMode;
import org.springframework.web.bind.annotation.RequestBody;
import net.officefloor.server.http.HttpException;
import net.officefloor.server.http.HttpStatus;
import net.officefloor.web.ObjectResponse;

/**
 * {@code POST /api/invoices/send} — send a DRAFT invoice from an {id} body and return the updated row.
 * Wired by {@code officefloor/rest/api/invoices/send.POST.yml}. Flips the invoice's status to SENT and
 * appends one {@code INVOICE_SENT} audit record (the kept record the request asks for), so the send
 * can be checked back later through the audit file even though the UI only shows the status. Only a
 * DRAFT invoice can be sent; sending is also what unlocks payment (see {@link InvoicesPayLogic}).
 */
public class InvoicesSendLogic {

    public void service(@RequestBody SendInvoice body, InvoiceRepository invoices, Audit audit,
            ObjectResponse<Invoice> response) {
        Long id = body.getId();
        if (id == null) {
            throw new HttpException(HttpStatus.BAD_REQUEST, "An invoice id is required");
        }
        Invoice invoice = invoices.findById(id)
                .orElseThrow(() -> new HttpException(HttpStatus.NOT_FOUND, "No such invoice"));
        if (!"DRAFT".equals(invoice.getStatus())) {
            throw new HttpException(HttpStatus.CONFLICT, "Only a draft invoice can be sent");
        }
        invoice.setStatus("SENT");
        Invoice saved = invoices.save(invoice);
        String amount = saved.getAmount().setScale(2, RoundingMode.HALF_UP).toPlainString();
        audit.record("INVOICE_SENT id=" + saved.getId() + " amount=" + amount);
        response.send(saved);
    }

    /** Request body for sending an invoice. */
    public static class SendInvoice {
        private Long id;

        public Long getId() {
            return id;
        }

        public void setId(Long id) {
            this.id = id;
        }
    }
}

